+import { getArena } from '../src/game/arenas';
+import { PROGRAM_ID } from '../src/game/programs';
+import { TOXIC, PLAYER } from '../src/game/config';
+import { ACTION, type InputFrame } from '../src/game/types';
+
+const DT = 1 / 60;
+const inputs: (InputFrame | null)[] = [null, null, null, null, null, null, null, null];
+
+function frame(held = 0, pressed = 0, mx = 0, my = 0): InputFrame {
+  return { mx, my, held, pressed };
+}
+
+const world = new World('training', ['TOXIC', 'BOT', 'WEDGE'], 0, getArena(0), true, PROGRAM_ID.TOXIC, 1, [PROGRAM_ID.PROBE]);
+const me = world.players[0];
+const bot = world.players[1];
+const behind = world.players[2];
+
+me.x = 400;
+me.y = 360;
+me.facing = 0;
+bot.x = 700;
+bot.y = 360;
+behind.active = true;
+behind.alive = true;
+behind.program = PROGRAM_ID.WEDGE;
+behind.x = 150;
+behind.y = 360;
+me.energy = PLAYER.energyMax;
+me.laserCd = 0;
+
+// Charge the jet.
+for (let i = 0; i < 60; i++) {
+  inputs[0] = frame(ACTION.CANDLE, i === 0 ? ACTION.CANDLE : 0);
+  world.step(DT, inputs);
+}
+console.log(
+  'fired | laserT',
+  me.laserT.toFixed(2),
+  'toxT',
+  me.toxT.toFixed(2),
+  'cone',
+  me.toxCone,
+  'energy',
+  me.energy.toFixed(0),
+  'laserCd',
+  me.laserCd.toFixed(2),
+  'facing',
+  me.facing.toFixed(2),
+  'bot hp',
+  bot.hp.toFixed(2),
+  'poison',
+  bot.poisonT.toFixed(2),
+  'behind hp',
+  behind.hp.toFixed(2),
+);
+
+// Rooted but aimable: press right, then up.
+const x0 = me.x;
+const y0 = me.y;
+const beforeFacing = me.facing;
+for (let i = 0; i < 18; i++) {
+  inputs[0] = frame(ACTION.CANDLE, 0, 0, -1);
+  world.step(DT, inputs);
+}
+console.log(
+  'aim | moved',
+  Math.hypot(me.x - x0, me.y - y0).toFixed(2),
+  'facing',
+  beforeFacing.toFixed(2),
+  '->',
+  me.facing.toFixed(2),
+  'expected -1.57',
+  'laserT',
+  me.laserT.toFixed(2),
+);
+
+// Finish the stream and check cooldown + that damage stops.
+for (let i = 0; i < 90; i++) {
+  inputs[0] = frame(ACTION.CANDLE, 0, 0, -1);
+  world.step(DT, inputs);
+}
+const hpAfter = bot.hp;
+for (let i = 0; i < 60; i++) {
+  inputs[0] = frame();
+  world.step(DT, inputs);
+}
+console.log('ended | laserT', me.laserT.toFixed(2), 'toxT', me.toxT.toFixed(2), 'bot hp steady', (hpAfter - bot.hp).toFixed(2), 'laserCd', me.laserCd.toFixed(2));
+
+// Cover blocks the jet: place a pillar between the bodies.
+const cw = new World('training', ['TOXIC', 'BOT'], 0, getArena(1), true, PROGRAM_ID.TOXIC, 1, [PROGRAM_ID.PROBE]);
+const a = cw.players[0];
+const b = cw.players[1];
+const pillar = cw.arena.pillars.find((r) => r.h > 80 && r.w > 40);
+if (pillar) {
+  a.x = pillar.x - 120;
+  a.y = pillar.y + pillar.h / 2;
+  a.facing = 0;
+  b.x = pillar.x + pillar.w + 200;
+  b.y = a.y;
+  b.active = true;
+  b.alive = true;
+  a.energy = PLAYER.energyMax;
+  a.laserCd = 0;
+  for (let i = 0; i < 70 && a.laserT <= 0; i++) {
+    inputs[0] = frame(ACTION.CANDLE, i === 0 ? ACTION.CANDLE : 0);
+    cw.step(DT, inputs);
+  }
+  console.log('cover | jet live', a.laserT > 0, 'target hp', b.hp, 'poison', b.poisonT.toFixed(2));
+}
+
+void TOXIC;
