export function drawBombMark(ctx, cx, cy, r) {
  const bodyR = r * 0.66;
  // body
  ctx.beginPath();
  ctx.arc(cx, cy + r * 0.12, bodyR, 0, TWO_PI);
  ctx.fill();
  // rim
  ctx.save();
  ctx.globalAlpha *= 0.9; // globalAlpha is number; *=
  ctx.lineWidth = max(1, r*0.14);
  ctx.beginPath();
  ctx.arc(..., bodyR, -0.4, Math.PI*1.1);
  ctx.stroke();
  ctx.restore();
  // neck + fuse
  ctx.beginPath();
  ctx.lineWidth = max(1.2, r*0.2);
  ctx.moveTo(cx + bodyR*0.55, cy - bodyR*0.55);
  ctx.lineTo(cx + r*0.8, cy - r*0.86);
  ctx.stroke();
  // spark
  ctx.fillRect(cx + r*0.72, cy - r*1.0, r*0.24, r*0.24);
}
