export function drawBombMark(ctx: CanvasRenderingContext2D, cx: number, cy: number, r: number): void {
  const bodyR = r * 0.64;
  const bodyY = cy + r * 0.14;
  ctx.beginPath();
  ctx.arc(cx, bodyY, bodyR, 0, Math.PI * 2);
  ctx.fill();
