import { ARENAS } from '../src/game/arenas';
import { MAX_PLAYERS, PLAYER } from '../src/game/config';
import { World } from '../src/game/world';

function rectHas(x: number, y: number, w: number, h: number, r = PLAYER.radius): boolean {
  const cx = Math.max(x, Math.min(x + w, r));
  const cy = Math.max(y, Math.min(y + h, r));
  return Math.hypot(r - cx, r - cy) < r;
}

for (const arena of ARENAS) {
  for (let bots = 1; bots <= 3; bots++) {
    const names = new Array(MAX_PLAYERS).fill('');
    names[0] = 'PLAYER';
    const programs: number[] = [];
    for (let i = 1; i <= bots; i++) {
      names[i] = `BOT${i}`;
      programs.push((i + 1) % 5);
    }
    const world = new World('gauntlet', names, 0, arena, false, 0, bots, programs, true);
    const p = world.players[0];
    const rows: string[] = [];
    let bad = 0;
    for (let i = 1; i <= bots; i++) {
      const b = world.players[i];
      const d = Math.hypot(b.x - p.x, b.y - p.y);
      let cover = false;
      for (const r of arena.pillars) if (rectHas(r.x, r.y, r.w, r.h, PLAYER.radius + 2) && true) {
        const nx = Math.max(r.x, Math.min(r.x + r.w, b.x));
        const ny = Math.max(r.y, Math.min(r.y + r.h, b.y));
        if (Math.hypot(b.x - nx, b.y - ny) < PLAYER.radius) cover = true;
      }
      if (cover || d < PLAYER.radius * 2) bad++;
      rows.push(`${Math.round(d)}${cover ? ' IN-COVER' : ''}`);
    }
    console.log(
      arena.name.padEnd(11),
      `${bots} bot${bots === 1 ? ' ' : 's'}`,
      rows.join(' | '),
      bad ? 'BAD' : 'ok',
      'respawn',
      [Math.round(world.spawnX[0]), Math.round(world.spawnY[0])].join(','),
      'start',
      [Math.round(p.x), Math.round(p.y)].join(','),
    );
  }
}
