private drawPusher(state: RenderState, t: number): void {
  const cfg = state.arena.pushers;
  if (!cfg) return;
  const ctx = this.ctx;
  const b = state.arena.bounds;
  const warn = state.pusherWarnT ?? 0;
  const flash = state.pusherFlashT ?? 0;
  // Plate: a band along the top edge. It glows through the warning, then slams.
  const band = cfg.band;
  ctx.save();
  ctx.fillStyle = 'rgba(255, 194, 77, 0.05)';
  ctx.fillRect(b.left, b.top, b.right - b.left, band);
  ctx.strokeStyle = state.arena.accent;
  if (warn > 0) {
    const p = 1 - warn / cfg.warn;      // 0..1 through the warning
    ctx.globalAlpha = 0.25 + 0.55 * p;
    ctx.lineWidth = 3 + 5 * p;
    ctx.beginPath();
    ctx.moveTo(b.left, b.top + band);
    ctx.lineTo(b.right, b.top + band);
    ctx.stroke();
    // Charge ticks across the plate.
    ctx.globalAlpha = 0.2 + 0.6 * p;
    ctx.lineWidth = 2;
    ctx.beginPath();
    const step = 64;
    for (let x = b.left + step * 0.5; x < b.right; x += step) {
      ctx.moveTo(x, b.top + band - 10);
      ctx.lineTo(x, b.top + band);
