const w = new World('match', names, 0, ARENAS[0], false, PROGRAM_ID.WEDGE);
w.phase = 'live';
const p0 = w.players[0];
const p1 = w.players[1];
p0.x = 700;
p0.y = 360;
p0.facing = 0;
p0.energy = 100;
p1.x = 300;
p1.y = 360;
p1.alive = true;
p1.facing = 0;
p1.energy = 100;

const frames: InputFrame[] = [];
for (let i = 0; i < 8; i++) frames.push({ mx: 0, my: 0, held: 0, pressed: 0 });

(w as unknown as { deployBarrier: (p: typeof p0) => boolean }).deployBarrier(p0);
const wall = w.barriers[0];
console.log('deployed', wall.active, 'hp', wall.hp, 'x', wall.x1.toFixed(0), wall.y1.toFixed(0), '->', wall.x2.toFixed(0), wall.y2.toFixed(0));

// Put one hostile bolt right in front of the wall, moving at it.
function shootAtWall(): void {
  const proj = w.projectiles.find((p) => !p.active);
  if (!proj) return;
  proj.active = true;
  proj.type = 3;
  proj.owner = -1;
  proj.x = wall.x1 - 40;
  proj.y = (wall.y1 + wall.y2) * 0.5;
  proj.prevX = proj.x;
  proj.prevY = proj.y;
  proj.vx = 700;
  proj.vy = 0;
  proj.radius = 5;
  proj.damage = 1;
  proj.fuse = 1;
  proj.bounces = 0;
  proj.armed = true;
  proj.deflects = 0;
  proj.blastRadius = 0;
}

let blocked = 0;
for (let n = 0; n < 8; n++) {
  shootAtWall();
  for (let t = 0; t < 4; t++) w.step(SIM_DT, frames);
  if (wall.active) blocked++;
