+import { SIM_DT } from '../src/game/config';
+import { ARENAS } from '../src/game/arenas';
+import { ACTION, type InputFrame } from '../src/game/types';
+import { World } from '../src/game/world';
+
+const arena = ARENAS.find((a) => a.name === 'RECYCLING BIN')!;
+const names = new Array(8).fill('BOT');
+names[0] = 'P0';
+
+function makeWorld(): World {
+  // Practice keeps the run alive after a knockdown so the full cycle can be watched.
+  const w = new World('gauntlet', names, 0, arena, true);
+  // Threat-free: this test is about the arm, not the wave.
+  (w as unknown as { updateGauntlet: () => void }).updateGauntlet = () => {};
+  return w;
+}
+
+function inputs(): InputFrame[] {
+  const arr: InputFrame[] = [];
+  for (let i = 0; i < 8; i++) arr.push({ mx: 0, my: 0, held: 0, pressed: 0 });
+  return arr;
+}
+
+function run(label: string, x: number, y: number, seconds: number): void {
+  const w = makeWorld();
+  const p = w.players[0];
+  p.x = x;
+  p.y = y;
+  p.vx = 0;
+  p.vy = 0;
+  const frames = inputs();
+  w.pusherT = arena.pushers!.warn + 0.02;
+  let diedAt = -1;
+  let maxY = y;
+  let yAtOneSec = 0;
+  for (let t = 0; t < seconds * 60; t++) {
+    // Threat-free: this test is about the arm, not the wave.
+    for (const s of w.sentries) s.active = false;
+    for (const x of w.worms) x.active = false;
+    for (const v of w.viruses) v.active = false;
+    for (const e of w.errors) e.active = false;
+    for (let i = 0; i < w.projectiles.length; i++) if (w.projectiles[i].owner < 0) w.projectiles[i].active = false;
+    w.step(SIM_DT, frames);
+    frames[0].pressed = 0;
+    if (t === 60) yAtOneSec = p.y;
+    if (t % 60 === 0) console.log('  t', (t / 60).toFixed(0), 'y', p.y.toFixed(0), 'front', w.pusherY.toFixed(0), 'ky', p.ky.toFixed(0), 'alive', p.alive);
+    if (!p.alive && diedAt < 0) diedAt = t / 60;
+    if (p.alive && p.y > maxY) maxY = p.y;
+  }
+  let props = 0;
+  for (let i = 0; i < w.props.length; i++) if (w.props[i].active) props++;
+  console.log(
+    `${label}: alive=${p.alive} diedAt=${diedAt.toFixed(2)} y=${p.y.toFixed(0)} maxY=${maxY.toFixed(
+      0,
+    )} y@1s=${yAtOneSec.toFixed(0)} pusherY=${w.pusherY.toFixed(0)} props=${props} kills=${w.gauntletKills}`,
+  );
+}
+
+run('MIDDLE   ', 995, 420, 36);
+run('SIDE     ', 260, 900, 36);
+run('TOP-LEFT ', 500, 200, 36);
+console.log('pillars', arena.pillars.length, 'thickness', arena.pushers!.thickness, 'travel', arena.pushers!.travel);
