export function drawHourglassMark(ctx, cx, cy, r): void {
  const w = r * 0.6;
  const h = r * 0.92;
  const waist = r * 0.16;
  ctx.beginPath();
  // Top cap and bottom cap keep the silhouette a glass, not just an X.
  ctx.moveTo(cx - w, cy - h);
  ctx.lineTo(cx + w, cy - h);
  ctx.lineTo(cx + waist, cy - h * 0.1);
  ctx.lineTo(cx + w, cy + h);
  ctx.lineTo(cx - w, cy + h);
  ctx.lineTo(cx - waist, cy - h * 0.1);
  ctx.closePath();
  ctx.fill();
  // Sand: a small bright notch near the waist, punched with the plate color.
}
