 * One-off generator: serialise the current tuning objects into ./tuning JSON.
 * Run once while config.ts still owns the literals, then delete.
 */
import { writeFileSync, mkdirSync } from 'node:fs';
import * as C from '../src/game/config';

const dir = 'src/game/tuning';
mkdirSync(dir, { recursive: true });

function pick<T extends Record<string, unknown>>(src: T, omit: string[] = []): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const key of Object.keys(src)) {
    if (omit.includes(key)) continue;
    out[key] = (src as Record<string, unknown>)[key];
  }
  return out;
}

const files: Record<string, Record<string, unknown>> = {
  player: {
    PLAYER: pick(C.PLAYER, ['swingHalfAngle', 'guardHalfAngle']),
    BOLT: C.BOLT,
    BUG: C.BUG,
    MINE: C.MINE,
  },
  programs: {
    WEDGE: C.WEDGE,
    FISHER: C.FISHER,
    SWEEP: pick(C.SWEEP, ['powerRise', 'powerSpan']),
    TOXIC: C.TOXIC,
    KABOOM: C.KABOOM,
    BUFFER: C.BUFFER,
  },
  threats: {
    GAUNTLET: C.GAUNTLET,
    WORM: C.WORM,
    VIRUS: C.VIRUS,
    SENTRY: C.SENTRY,
    CASCADING_ERROR: C.CASCADING_ERROR,
    THRALL: C.THRALL,
    FIREWALL: C.FIREWALL,
  },
  campaign: {
    CAMPAIGN: C.CAMPAIGN,
  },
  world: {
    CAMERA: C.CAMERA,
    FALL: C.FALL,
    FILE_PROP: C.FILE_PROP,
    ARENA: C.ARENA,
    TRAVERSE: C.TRAVERSE,
    POWERUP: C.POWERUP,
    ROUND: C.ROUND,
    TRAINING: C.TRAINING,
    NET: C.NET,
    ATTRACT: C.ATTRACT,
  },
};

for (const [name, body] of Object.entries(files)) {
  writeFileSync(`${dir}/${name}.json`, JSON.stringify(body, null, 2) + '\n');
  console.log('wrote', `${dir}/${name}.json`);
}
"}}


