+import { World } from '../src/game/world';
+import { BotBrain } from '../src/game/bot';
+import { ARENAS } from '../src/game/arenas';
+import { SIM_DT } from '../src/game/config';
+import { PROGRAM_ID } from '../src/game/programs';
+import { EV, type InputFrame } from '../src/game/types';
+
+function run(wave: number, program: number, seconds: number, seed: number) {
+  const world = new World('gauntlet', ['TEST'], 0, ARENAS[0], false, program);
+  world.seedAttractRun(wave);
+  const brain = new BotBrain(0, 'digital', 0, seed);
+  const input: InputFrame = { mx: 0, my: 0, held: 0, pressed: 0 };
+  let guardFrames = 0;
+  let deflects = 0;
+  let sentryShots = 0;
+  let hits = 0;
+  let maxChain = 0;
+  const steps = Math.floor(seconds / SIM_DT);
+  for (let step = 0; step < steps; step++) {
+    brain.think(world, input, SIM_DT);
+    const before = world.players[0].hp;
+    world.step(SIM_DT, [input]);
+    if (world.players[0].guardT > 0) guardFrames++;
+    if (world.players[0].hp < before) hits++;
+    for (let i = 0; i < world.eventCount; i++) {
+      const e = world.events[i];
+      if (e.kind === EV.DEFLECT && e.slot === 0) {
+        deflects++;
+        maxChain = Math.max(maxChain, e.power);
+      }
+      if (e.kind === EV.SENTRY_SHOOT) sentryShots++;
+    }
+    world.clearEvents();
+    if (world.gauntletOver) break;
+  }
+  const p = world.players[0];
+  return {
+    program,
+    wave,
+    alive: p.alive,
+    guardSeconds: +(guardFrames * SIM_DT).toFixed(1),
+    deflects,
+    sentryShots,
+    maxChain,
+    hits,
+    hp: p.hp,
+  };
+}
+
+for (const program of [PROGRAM_ID.PROBE, PROGRAM_ID.SWEEP, PROGRAM_ID.ATOMIZE]) {
+  for (const seed of [11, 29, 47]) {
+    console.log(JSON.stringify(run(72, program, 45, seed)));
+  }
+}
